select r.id||'-M'||lpad(t.n::text,2,'0'), r.id, t.name, t.course,
  round((t.price*(0.95+(abs(hashtext(r.id||t.name))%16)/100.0))::numeric,2),
  array(select distinct x from unnest(t.tags::text[]
    || case when r.halal_certified or 'vegetarian'=any(t.tags::text[]) then '{halal}'::text[] else '{}' end
    || case when 'vegan'=any(t.tags::text[]) or 'gluten_free'=any(t.tags::text[]) or abs(hashtext(r.id||t.name||'n'))%2=0 then '{nut_free}'::text[] else '{}' end) x order by x)
from public.restaurants r join t on t.cuisine=r.cuisine
on conflict (id) do nothing;

-- keep price_per_person in line with the generated menus (average main + $6 for a side/drink)
update public.restaurants r set price_per_person=round(m.avg_main+6,2)
from (select restaurant_id, avg(price) avg_main from public.menu_items where course='main' group by restaurant_id) m
where m.restaurant_id=r.id;

